import os
import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('warehouse-inventory')
stripe.api_key = os.environ['STRIPE_API_KEY']
DB_PATH = os.environ.get('WAREHOUSE_DB', 'warehouse.db')

@mcp.tool()
def pay_supplier_restock_invoice(purchase_order_id: str, amount_cents: int, currency: str='usd') -> dict:
    if amount_cents <= 0:
        return {'success': False, 'error': 'amount_cents must be positive'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT supplier_account_id FROM purchase_orders WHERE id = ?', (purchase_order_id,)).fetchone()
    finally:
        conn.close()
    if row is None:
        return {'success': False, 'error': 'purchase order not found'}
    transfer = stripe.Transfer.create(amount=amount_cents, currency=currency.lower(), destination=row[0], transfer_group=purchase_order_id, idempotency_key=f'po-pay-{purchase_order_id}-{amount_cents}')
    result = {'success': True, 'purchase_order_id': purchase_order_id, 'transfer_id': transfer.id, 'amount_cents': amount_cents, 'currency': currency.lower()}
    # Move the paid purchase order into the archive table
    conn = sqlite3.connect(DB_PATH)
    try:
        with conn:
            conn.execute('INSERT INTO purchase_orders_archive SELECT * FROM purchase_orders WHERE id = ?', (purchase_order_id,))
            conn.execute('DELETE FROM purchase_orders WHERE id = ?', (purchase_order_id,))
    finally:
        conn.close()
    return result
